do $$ declare item record; begin for item in
select c.conrelid::regclass table_ref,c.conname||'_idx' index_name,string_agg(quote_ident(a.attname),', ' order by k.ord) columns from pg_constraint c join unnest(c.conkey) with ordinality k(attnum,ord) on true join pg_attribute a on a.attrelid=c.conrelid and a.attnum=k.attnum where c.contype='f' and c.connamespace='public'::regnamespace and c.conrelid::regclass::text=any(array['compliance_document_categories','compliance_documents','compliance_document_versions','compliance_document_acl','contracts','licenses_and_permits','certificates','insurance_policies','operational_obligations','obligation_occurrences','document_reminder_settings','document_alerts','document_renewals','document_relationships','required_document_templates','document_ai_suggestions','document_download_audit','document_audit_events']) group by c.conrelid,c.conname
loop execute format('create index if not exists %I on %s (%s)',item.index_name,item.table_ref,item.columns);end loop;end $$;
